contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Call sequence: ensure not initialized, call SetMinSum once with _val,
    // then check that c.MinSum() equals the provided _val.
    // This holds for original P (assignment) but is violated by mutant M (which adds).
    function run(uint _val) public {
        // precondition: contract must not be initialized yet
        // ensure caller has no effect on c; we only require not initialized
        require(!_isInitialized());

        c.SetMinSum(_val);

        // Observe MinSum via public getter and assert it equals the provided value
        assert(c.MinSum() == _val);
    }

    // helper to read the 'intitalized' flag isn't available (it's internal),
    // so we approximate by attempting to call SetMinSum with zero and seeing it doesn't revert.
    // But we cannot catch reverts; instead we rely on MinSum getter to ensure initial state.
    // Provide a view that checks initialized indirectly by comparing MinSum before any change.
    function _isInitialized() internal view returns (bool) {
        // We treat MinSum==0 as likely uninitialized; to be safe, require caller to use values accordingly.
        // This internal helper is only used in require above to avoid calling reverts on c.
        // If MinSum is nonzero already, consider it initialized.
        return (c.MinSum() != 0);
    }

    // receive and fallback not used
    receive() external payable {}
}

