contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz params: actor address and values used when setting MinSum and deposits/collect
    function testFuzz_property(address actor, uint256 setVal, uint256 deposit, uint256 lockTime, uint256 collectAmt) public {
        // keep actor non-zero
        vm.assume(actor != address(0));
        // keep amounts within reasonable bounds to avoid overflow in the contract's simple arithmetic
        setVal = bound(setVal, 0, type(uint256).max / 4);
        deposit = bound(deposit, 0, type(uint256).max / 4);
        collectAmt = bound(collectAmt, 0, type(uint256).max / 4);
        lockTime = bound(lockTime, 0, 1000000);

        // ensure actor has ether to deposit and collect
        vm.deal(actor, deposit + collectAmt + 1);

        // Before initializing, set MinSum once using SetMinSum with fuzzed setVal
        vm.prank(actor);
        c.SetMinSum(setVal);

        // initialize log/address settings then lock them (to mimic usage path)
        vm.prank(actor);
        c.SetLogFile(address(this));
        vm.prank(actor);
        c.Initialized();

        // actor deposits deposit wei
        if (deposit > 0) {
            vm.prank(actor);
            c.Put{value: deposit}(lockTime);
        } else {
            // even if deposit is zero, call fallback to exercise fallback path
            vm.prank(actor);
            (bool ok, ) = address(c).call{value: 0}("");
            // ignore ok
            ok;
        }

        // record MinSum before Collect
        uint256 before = c.MinSum();

        // fast-forward time past unlock if needed
        vm.warp(block.timestamp + lockTime + 1);

        // attempt Collect from actor; we observe only c's public getters
        vm.prank(actor);
        bool ok;
        try c.Collect(collectAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        // The specification: Collect must NOT change MinSum for the reference contract
        // (the mutant that used += in SetMinSum can cause MinSum to differ after operations triggered here)
        uint256 after = c.MinSum();

        assertTrue(before == after);
    }
}

