pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: the initial MinSum value to set, an amount to deposit, and the collect amount.
    // We keep domains wide but avoid trivial overflows by bounding values sensibly.
    function testFuzz_property(uint256 initMin, uint256 depositAmt, uint256 collectAmt) public {
        // keep values in a wide admissible range
        initMin = bound(initMin, 0, type(uint128).max);
        depositAmt = bound(depositAmt, 0, 1 ether);
        collectAmt = bound(collectAmt, 0, 1 ether);

        // deploy an adversarial recipient that will reject the transfer so we can observe behavior
        Reverter r = new Reverter();

        // set MinSum once (before initialization flip)
        c.SetMinSum(initMin);

        // set log file to some harmless address (EOA-like). Use this test contract as log - it fits the LogFile interface shape.
        c.SetLogFile(address(this));

        // initialize contract so SetMinSum cannot be called again
        c.Initialized();

        // fund an actor and have them put some funds into c
        address actor = address(0xBEEF);
        vm.deal(actor, depositAmt + 1);
        vm.prank(actor);
        // call Put with some lock time 0 so funds are immediately available for Collect condition check
        c.Put{value: depositAmt}(0);

        // read MinSum before Collect
        uint256 before = c.MinSum();

        // route the Collect call from the actor but make msg.sender be the Reverter by having Reverter perform a low-level call into Collect
        // We need an attacker contract that will call c.Collect on behalf of actor while being the recipient of the transfer (so msg.sender inside c is Reverter)
        // To cause a failing transfer, the Reverter will reject incoming funds in its fallback/receive, so when c attempts to call msg.sender.call{value: _am} it will fail.

        // Ensure Reverter has no balance so transfer fails; we still instruct actor to invoke Reverter which then calls c.Collect
        vm.prank(actor);
        // actor calls reverter which then calls c.Collect(collectAmt)
        r.callCollect(address(c), collectAmt);

        // read MinSum after Collect
        uint256 after = c.MinSum();

        // The universal property: Collect must not change MinSum; reference holds for all inputs, mutant breaks for some
        assertTrue(before == after);
    }
}

// Minimal adversarial helper: it rejects incoming ETH so that low-level call from C to msg.sender fails
contract Reverter {
    // allow this contract to be instructed to call C.collect on behalf of an external actor
    function callCollect(address caddr, uint256 amt) external {
        C(caddr).Collect(amt);
    }

    // reject any incoming ether to force the low-level call in Collect to fail
    fallback() external payable {
        revert("reject");
    }
    receive() external payable {
        revert("reject");
    }
}

