pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz parameters: depositor address, initialMin (for SetMinSum), deposit amount, collect amount
    function testFuzz_property(address depositor, uint256 initialMin, uint256 depositAmt, uint256 collectAmt) public {
        // keep depositor as non-zero and within realistic bounds
        vm.assume(depositor != address(0));
        // bound amounts to avoid overflow/zero-edge that are not interesting
        depositAmt = bound(depositAmt, 1, 1 ether);
        collectAmt = bound(collectAmt, 1, 1 ether);
        initialMin = bound(initialMin, 0, 1 ether);

        // deploy a reverter helper that will cause the low-level call in Collect to fail
        Reverter rev = new Reverter();

        // initialize MinSum using the public setter (reference sets exactly, mutant adds)
        c.SetMinSum(initialMin);
        // set Log and mark initialized so setters cannot be called again
        c.SetLogFile(address(this));
        c.Initialized();

        // fund the depositor so they can deposit
        vm.deal(depositor, depositAmt);
        // make depositor put funds (via fallback/Put) with zero extra lock time
        vm.prank(depositor);
        // call fallback by sending value, it routes to Put(0)
        (bool s,) = address(c).call{value: depositAmt}("");
        require(s);

        // read MinSum before Collect
        uint256 before = c.MinSum();

        // Now set up the contract to send to the Reverter address: we need the holder to be the reverter
        // To make Collect attempt sending to an address, that address must be msg.sender for Collect.
        // So we will have the reverter call Collect as msg.sender; give it some balance by sending ETH
        vm.deal(address(rev), 0);

        // ensure depositor's account has enough balance and that holder unlockTime is in past so Collect can proceed
        // warp forward so unlockTime (which was zero for Put(0)) is in the past relative to now
        vm.warp(block.timestamp + 1);

        // Now have the Reverter attempt to Collect; give it no balance but we will make the Acc entry correspond to rev by using the author's pattern:
        // We need Acc[msg.sender] for reverter to have sufficient balance and unlockTime. We cannot directly set Acc for rev from here,
        // but we can simulate: make the reverter deposit by calling Put via its fallback. First fund rev, then have it call Put
        vm.deal(address(rev), depositAmt);
        // reverter invokes fallback on c to deposit
        rev.callPut{value: depositAmt}(address(c));

        // Now ensure conditions: its balance >= MinSum and >= collectAmt and block.timestamp > unlockTime
        // bound collectAmt so that it is <= deposited amount
        collectAmt = bound(collectAmt, 1, depositAmt);

        // Have reverter call Collect; the reverter's receive will revert when receiving funds, so the low-level call inside Collect will fail
        // That leads Collect to revert in reference (since it checks _s and reverts if false). We catch the call to observe behavior.
        bool ok;
        try rev.callCollect(address(c), collectAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        // After the Collect attempt (whether it reverted or not), the reference contract guarantees MinSum remains unchanged for all admissible inputs.
        // Single assertion checking that property by reading c.MinSum()
        assertTrue(c.MinSum() == before);
    }
}

// adversarial helper that causes any incoming payment via fallback/receive to revert, and exposes methods to interact with C
contract Reverter {
    // deposit into C by calling fallback on target
    function callPut(address target) public payable {
        (bool s,) = target.call{value: msg.value}("");
        require(s);
    }

    // ask C to Collect(amount) as this contract
    function callCollect(address target, uint256 amt) public returns (bool) {
        C c = C(payable(target));
        c.Collect(amt);
        return true;
    }

    // revert on any incoming funds to simulate failing transfer
    receive() external payable {
        revert("no receive");
    }
}
